// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.prank(address(this));
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        bool decoded = false;
        if (ok && ret.length >= 32) {
            decoded = abi.decode(ret, (bool));
        } else if (ok && ret.length == 0) {
            decoded = false;
        }
        assertTrue(!ok || decoded);
    }
}
